return {
  -- 1. Setup Treesitter (Ensure 'org' parser is installed)
  {
    "nvim-treesitter/nvim-treesitter",
    opts = function(_, opts)
      opts.ensure_installed = opts.ensure_installed or {}
      if type(opts.ensure_installed) == "table" then
        if not vim.tbl_contains(opts.ensure_installed, "org") then
          table.insert(opts.ensure_installed, "org")
        end
      end
    end,
  },

  -- 2. Setup Autocompletion for blink.cmp (Properly scoped to org filetype only)
  {
    "saghen/blink.cmp",
    opts = function(_, opts)
      opts.sources = opts.sources or {}
      opts.sources.per_filetype = opts.sources.per_filetype or {}
      opts.sources.per_filetype.org = { "orgmode" }

      opts.sources.providers = opts.sources.providers or {}
      opts.sources.providers.orgmode = {
        name = "Orgmode",
        module = "orgmode.org.autocompletion.blink",
        fallbacks = { "buffer" },
      }
    end,
  },

  -- 3. Image Support: Keep image.nvim for markdown, but remove 'org' so it doesn't fight snacks.nvim
  {
    "3rd/image.nvim",
    opts = {
      backend = "kitty",
      integrations = {
        markdown = {
          enabled = true,
          clear_in_insert_mode = true, -- Prevents buffer rescans while typing
          download_remote_images = true,
          only_render_image_at_cursor = false,
          filetypes = { "markdown", "vimwiki" }, -- Removed "org"
        },
      },
    },
  },

  -- 4. Main Orgmode Configuration
  {
    "nvim-orgmode/orgmode",
    event = "VeryLazy",
    ft = { "org" },
    dependencies = {
      "nvim-treesitter/nvim-treesitter",
      "nvim-orgmode/org-bullets.nvim",
    },
    config = function()
      require("orgmode").setup({
        -- Paths for Agenda and Capture
        org_agenda_files = {
          "~/Documents/zettelkasten-notes/top/**/*.org",
          "~/Documents/zettelkasten-notes/cs50/**/*.org",
          "~/Documents/zettelkasten-notes/5th-sem/projects/**/*.org",
          "~/Documents/zettelkasten-notes/6th-sem/artificialCognitiveSystem/**/*.org",
          "~/Documents/zettelkasten-notes/6th-sem/iotAndSmartSensors/**/*.org",
          "~/Documents/zettelkasten-notes/6th-sem/elective/**/*.org",
        },
        org_default_notes_file = "~/Documents/zettelkasten-notes/top/refile.org",

        -- Visuals & Syntax
        org_hide_emphasis_markers = true,
        org_startup_indented = false,
        org_todo_keywords = { "TODO", "NEXT", "|", "DONE", "CANCELLED" },

        -- LaTeX/MathJax is handled directly via snacks.nvim math renderer.
        -- Disabled experimental regex highlighter to avoid lag:
        -- org_highlight_latex_and_related = "entities",
      })

      require("org-bullets").setup()
    end,
  },
}
